import {
    ActivityIndicator,
    Pressable,
    ScrollView,
    StyleSheet,
    Text,
    View,
} from 'react-native';

import {
    useEffect,
    useState,
} from 'react';

import {
    useSafeAreaInsets,
} from 'react-native-safe-area-context';

import type { HomeStackScreenProps } from '../navigation/types';

import BookingItem from '../components/BookingItem';
import CustomButton from '../components/CustomButton';

import {
    COLORS,
    RADIUS,
    SPACING,
    TYPOGRAPHY,
} from '../constants/theme';

import {
    fetchEventById,
    TicketmasterEvent,
} from '../api/api';

type Props =
    HomeStackScreenProps<'Booking'>;

const SERVICE_FEE = 2.5;

export default function BookingScreen({
    navigation,
    route,
}: Props) {
    const insets =
        useSafeAreaInsets();

    const {
        eventId,
        quantity: initialQuantity,
        ticketType,
        ticketPrice,
    } = route.params;

    const [event, setEvent] =
        useState<TicketmasterEvent | null>(
            null,
        );

    const [loading, setLoading] =
        useState(true);

    const [error, setError] =
        useState<string | null>(null);

    const [quantity, setQuantity] =
        useState(initialQuantity);

    useEffect(() => {
        const loadEvent = async () => {
            try {
                setLoading(true);
                setError(null);

                const data =
                    await fetchEventById(
                        eventId,
                    );

                setEvent(data);
            } catch (err) {
                setError(
                    err instanceof Error
                        ? err.message
                        : 'Failed to load event.',
                );
            } finally {
                setLoading(false);
            }
        };

        loadEvent();
    }, [eventId]);

    const formatTime = (
        time?: string,
    ) => {
        if (!time) {
            return null;
        }

        return time.slice(0, 5);
    };

    const formatDate = (
        date?: string,
        time?: string,
    ) => {
        if (!date) {
            return 'Date TBA';
        }

        const parsedDate =
            new Date(date);

        const formattedDate =
            parsedDate.toLocaleDateString(
                'en-GB',
                {
                    day: '2-digit',
                    month: 'short',
                },
            );

        const formattedTime =
            formatTime(time);

        return formattedTime
            ? `${formattedDate} • ${formattedTime}`
            : formattedDate;
    };

    const getLocation = () => {
        const venue =
            event?._embedded
                ?.venues?.[0];

        if (!venue) {
            return 'Location TBA';
        }

        const parts = [
            venue.name,
            venue.city?.name,
        ].filter(Boolean);

        return (
            parts.join(', ') ||
            'Location TBA'
        );
    };

    const ticketTotal =
        quantity * ticketPrice;

    const total =
        ticketTotal +
        SERVICE_FEE;

    const handleCancel = () => {
        navigation.goBack();
    };

    const handleContinue = () => {
        navigation.navigate(
            'Payment',
            {
                eventId,
                quantity,
                ticketType,
                ticketPrice,
            },
        );
    };

    if (loading) {
        return (
            <View
                style={
                    styles.center
                }
            >
                <ActivityIndicator
                    size="large"
                    color={
                        COLORS.primary
                    }
                />

                <Text
                    style={
                        styles.loadingText
                    }
                >
                    Loading booking...
                </Text>
            </View>
        );
    }

    if (error || !event) {
        return (
            <View
                style={
                    styles.center
                }
            >
                <Text
                    style={
                        styles.errorTitle
                    }
                >
                    Event not found
                </Text>

                <Text
                    style={
                        styles.errorText
                    }
                >
                    {error ??
                        "We couldn't load this event."}
                </Text>

                <CustomButton
                    title="Go back"
                    variant="primary"
                    onPress={() =>
                        navigation.goBack()
                    }
                />
            </View>
        );
    }

    const imageUrl =
        event.images?.[0]?.url;

    return (
        <View
            style={
                styles.container
            }
        >
            <ScrollView
                showsVerticalScrollIndicator={
                    false
                }
                contentContainerStyle={[
                    styles.content,
                    {
                        paddingTop:
                            insets.top +
                            SPACING.sm,
                        paddingBottom:
                            insets.bottom +
                            110,
                    },
                ]}
            >
                {/* Header */}
                <View
                    style={
                        styles.header
                    }
                >
                    <Pressable
                        onPress={
                            handleCancel
                        }
                        hitSlop={8}
                        accessibilityRole="button"
                    >
                        <Text
                            style={
                                styles.cancel
                            }
                        >
                            Cancel
                        </Text>
                    </Pressable>

                    <Text
                        style={
                            styles.headerTitle
                        }
                    >
                        Booking Summary
                    </Text>

                    <View
                        style={
                            styles.headerSpacer
                        }
                    />
                </View>

                {/* Progress */}
                <View
                    style={
                        styles.steps
                    }
                >
                    <View
                        style={
                            styles.stepItem
                        }
                    >
                        <View
                            style={
                                styles.completedCircle
                            }
                        >
                            <Text
                                style={
                                    styles.completedNumber
                                }
                            >
                                ✓
                            </Text>
                        </View>

                        <Text
                            style={
                                styles.stepText
                            }
                        >
                            Tickets
                        </Text>
                    </View>

                    <View
                        style={
                            styles.stepLine
                        }
                    />

                    <View
                        style={
                            styles.stepItem
                        }
                    >
                        <View
                            style={
                                styles.activeCircle
                            }
                        >
                            <Text
                                style={
                                    styles.activeNumber
                                }
                            >
                                2
                            </Text>
                        </View>

                        <Text
                            style={
                                styles.activeText
                            }
                        >
                            Summary
                        </Text>
                    </View>

                    <View
                        style={
                            styles.stepLine
                        }
                    />

                    <View
                        style={
                            styles.stepItem
                        }
                    >
                        <View
                            style={
                                styles.circle
                            }
                        >
                            <Text
                                style={
                                    styles.number
                                }
                            >
                                3
                            </Text>
                        </View>

                        <Text
                            style={
                                styles.stepText
                            }
                        >
                            Payment
                        </Text>
                    </View>

                    <View
                        style={
                            styles.stepLine
                        }
                    />

                    <View
                        style={
                            styles.stepItem
                        }
                    >
                        <View
                            style={
                                styles.circle
                            }
                        >
                            <Text
                                style={
                                    styles.number
                                }
                            >
                                4
                            </Text>
                        </View>

                        <Text
                            style={
                                styles.stepText
                            }
                        >
                            Confirmation
                        </Text>
                    </View>
                </View>

                {/* Introduction */}
                <View
                    style={
                        styles.intro
                    }
                >
                    <Text
                        style={
                            styles.title
                        }
                    >
                        Review your booking
                    </Text>

                    <Text
                        style={
                            styles.subtitle
                        }
                    >
                        Check your tickets before
                        continuing to payment.
                    </Text>
                </View>

                {/* Selected event */}
                <BookingItem
                    title={event.name}
                    imageUrl={
                        imageUrl
                            ? {
                                  uri: imageUrl,
                              }
                            : require('../../assets/images/festival.jpg')
                    }
                    date={formatDate(
                        event.dates
                            ?.start
                            ?.localDate,
                        event.dates
                            ?.start
                            ?.localTime,
                    )}
                    location={getLocation()}
                    ticketType={
                        ticketType
                    }
                    quantity={
                        quantity
                    }
                    price={
                        ticketPrice
                    }
                    onQuantityChange={
                        setQuantity
                    }
                />

                {/* Order summary */}
                <View
                    style={
                        styles.summary
                    }
                >
                    <Text
                        style={
                            styles.summaryTitle
                        }
                    >
                        Order Summary
                    </Text>

                    <View
                        style={
                            styles.priceRow
                        }
                    >
                        <Text
                            style={
                                styles.label
                            }
                        >
                            {quantity} ×{' '}
                            {ticketType}
                        </Text>

                        <Text
                            style={
                                styles.value
                            }
                        >
                            £
                            {ticketTotal.toFixed(
                                2,
                            )}
                        </Text>
                    </View>

                    <View
                        style={
                            styles.priceRow
                        }
                    >
                        <View>
                            <Text
                                style={
                                    styles.label
                                }
                            >
                                Service fee
                            </Text>

                            <Text
                                style={
                                    styles.secondaryLabel
                                }
                            >
                                Booking service fee
                            </Text>
                        </View>

                        <Text
                            style={
                                styles.value
                            }
                        >
                            £
                            {SERVICE_FEE.toFixed(
                                2,
                            )}
                        </Text>
                    </View>

                    <View
                        style={
                            styles.divider
                        }
                    />

                    <View
                        style={
                            styles.totalRow
                        }
                    >
                        <Text
                            style={
                                styles.totalLabel
                            }
                        >
                            Total
                        </Text>

                        <Text
                            style={
                                styles.totalValue
                            }
                        >
                            £
                            {total.toFixed(
                                2,
                            )}
                        </Text>
                    </View>
                </View>
            </ScrollView>

            {/* Footer */}
            <View
                style={[
                    styles.footer,
                    {
                        paddingBottom:
                            insets.bottom +
                            SPACING.sm,
                    },
                ]}
            >
                <CustomButton
                    title="Continue to Payment"
                    variant="primary"
                    onPress={
                        handleContinue
                    }
                />
            </View>
        </View>
    );
}

